def solve(s):
    toks = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            toks.append(int(s[i:j]))
            i = j
            continue
        toks.append(c)
        i += 1

    pos = 0

    def peek():
        return toks[pos] if pos < len(toks) else None

    def expr():
        nonlocal pos
        v = term()
        while peek() in ('+', '-'):
            op = toks[pos]
            pos += 1
            r = term()
            v = v + r if op == '+' else v - r
        return v

    def term():
        nonlocal pos
        v = factor()
        while peek() in ('*', '/'):
            op = toks[pos]
            pos += 1
            r = factor()
            if op == '*':
                v = v * r
            else:
                v = v // r
        return v

    def factor():
        nonlocal pos
        t = peek()
        if t == '-':
            pos += 1
            return -factor()
        if t == '+':
            pos += 1
            return factor()
        if t == '(':
            pos += 1
            v = expr()
            if peek() == ')':
                pos += 1
            return v
        pos += 1
        return t

    return expr()

def solve(text, k):
    counts = {}
    for w in text.split():
