def solve(text):
    stats = {}
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        parts = line.split(None, 1)
        if not parts:
            continue
        level = parts[0]
        rest = parts[1] if len(parts) > 1 else ""
        comp = rest.split(":", 1)[0].strip()
        if comp not in stats:
            stats[comp] = [0, 0]
        if level == "ERROR":
            stats[comp][0] += 1
        elif level == "WARN":
            stats[comp][1] += 1
    items = sorted(stats.items(), key=lambda kv: (-kv[1][0], -kv[1][1], kv[0]))
    return "\n".join("%s %d %d" % (c, e, w) for c, (e, w) in items)

LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]


def winner(b):
    for a, c, d in LINES:
        if b[a] != '.' and b[a] == b[c] == b[d]:
            return b[a]
    return None


def other(s):
    return 'O' if s == 'X' else 'X'


def best(b, side, memo):
    key = (b, side)
    if key in memo:
        return memo[key]
    w = winner(b)
    if w is not None:
        res = (1 if w == side else -1, -1)
        memo[key] = res
        return res
    if '.' not in b:
        memo[key] = (0, -1)
        return (0, -1)
    bestscore = None
    bestmove = -1
    for i in range(9):
        if b[i] != '.':
            continue
        nb = b[:i] + side + b[i+1:]
        sc, _ = best(nb, other(side), memo)
        sc = -sc
        if bestscore is None or sc > bestscore:
            bestscore = sc
            bestmove = i
    memo[key] = (bestscore, bestmove)
    return (bestscore, bestmove)


